-- Bound CSV duplicate checks and their transactional snapshot to one identity bucket.
-- Rejected catalog rows participate too; a CSV insertion must not silently revive them.
CREATE INDEX idx_catalog_products_identity_bucket
  ON knowledge_catalog_products(manufacturer_id, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(UPPER(normalized_model), ' ', ''), '!', ''), '"', ''), '#', ''), '$', ''), '%', ''), '&', ''), '''', ''), '(', ''), ')', ''), '*', ''), '+', ''), ',', ''), '-', ''), '.', ''), '/', ''), ':', ''), ';', ''), '<', ''), '=', ''), '>', ''), '?', ''), '@', ''), '[', ''), '\', ''), ']', ''), '^', ''), '_', ''), '`', ''), '{', ''), '|', ''), '}', ''), '~', ''), 'EDITION', ''), 'MARK', 'MK'), 'MK4', 'MKIV'), 'MK3', 'MKIII'), 'MK2', 'MKII'), 'MK1', 'MKI'), 'REV4', 'IV'), 'REV3', 'III'), 'REV2', 'II'));
